<template><AppPage title="Machines" :subtitle="`${store.items.length} virtual machine instances`"><template #actions><v-btn color="primary" prepend-icon="mdi-plus" to="/machines/new">Create machine</v-btn></template>
  <ResourceToolbar v-model:search="search" search-label="Search by name, class, image, or IP" :loading="store.loading" @refresh="store.load()"/>
  <LoadingState v-if="store.loading && !store.items.length"/><AppAlert v-else-if="store.error" type="error">{{ store.error }} <v-btn class="ml-2" size="small" @click="store.load()">Retry</v-btn></AppAlert><EmptyState v-else-if="!store.items.length" title="No machines" message="Create a machine to start running workloads."><v-btn color="primary" to="/machines/new">Create machine</v-btn></EmptyState><EmptyState v-else-if="!filtered.length" title="No matching machines" message="Try a different name, class, image, or IP address." icon="mdi-magnify"/>
  <v-card v-else variant="outlined" class="ic-table-overflow"><v-data-table :headers="headers" :items="filtered" :loading="store.loading" item-key="name" hover><template #item.name="{item}"><router-link :to="`/machines/${item.name}`" class="font-weight-medium text-primary">{{ item.name }}</router-link></template><template #item.state="{item}"><StatusBadge :state="item.state"/></template><template #item.ips="{item}"><CopyChip v-for="ip in item.ips" :key="ip" :text="ip" class="mr-1"/></template><template #item.createdAt="{item}"><span :title="absoluteTime(item.createdAt)">{{ relativeTime(item.createdAt) }}</span></template><template #item.actions="{item}"><div class="d-flex ga-1 mobile-critical"><v-btn size="small" variant="text" :icon="item.power==='On'?'mdi-power-off':'mdi-power'" :aria-label="`${item.power==='On'?'Power off':'Power on'} ${item.name}`" @click.stop="store.setPower(item.name,item.power==='On'?'Off':'On')"/><v-btn size="small" variant="text" icon="mdi-delete-outline" color="error" :aria-label="`Delete machine ${item.name}`" @click.stop="openDelete(item.name)"/></div></template></v-data-table></v-card>
  <ConfirmDialog v-model="deleteOpen" title="Delete machine?" :resource-name="pendingDelete" message="This machine will be permanently deleted." :loading="deleting" :error="deleteError" @confirm="remove"/>
</AppPage></template>
<script setup lang="ts">
import { computed,ref } from 'vue'; import AppPage from '@/components/app/AppPage.vue'; import ResourceToolbar from '@/components/resource/ResourceToolbar.vue'; import LoadingState from '@/components/feedback/LoadingState.vue'; import EmptyState from '@/components/feedback/EmptyState.vue'; import AppAlert from '@/components/feedback/AppAlert.vue'; import ConfirmDialog from '@/components/feedback/ConfirmDialog.vue'; import StatusBadge from '@/components/common/StatusBadge.vue'; import CopyChip from '@/components/common/CopyChip.vue'; import { useMachinesStore } from '@/stores/machines'; import { relativeTime,absoluteTime } from '@/composables/useTime'
const store=useMachinesStore(),search=ref(''),deleteOpen=ref(false),pendingDelete=ref(''),deleting=ref(false),deleteError=ref<string|null>(null)
const headers=[{title:'Name',key:'name'},{title:'Status',key:'state'},{title:'Class',key:'machineClass'},{title:'Image',key:'image'},{title:'IP addresses',key:'ips'},{title:'Created',key:'createdAt'},{title:'Actions',key:'actions',sortable:false}]
const filtered=computed(()=>{const q=search.value.toLowerCase();return q?store.items.filter(x=>[x.name,x.machineClass,x.image,...x.ips].some(value=>value.toLowerCase().includes(q))):store.items})
function openDelete(name:string){pendingDelete.value=name;deleteError.value=null;deleteOpen.value=true}
async function remove(){deleting.value=true;deleteError.value=null;try{await store.deleteMachine(pendingDelete.value);deleteOpen.value=false}catch(error){deleteError.value=error instanceof Error?error.message:String(error)}finally{deleting.value=false}}
</script>
